import asyncio

import pytest

from board.telemetry.protocol import TelemetryMessage, TelemetrySource
from board.telemetry.worker import TelemetryWorker


def make_message(sequence: int = 1) -> TelemetryMessage:
    return TelemetryMessage(
        # protocol_version = '0.1'
        # message_id is autogenerated
        # timestamp is autogenerated
        event_type="metrics.batch",
        sequence=sequence,
        source=TelemetrySource(
            machine_id="training-node-01",
            hostname="gpu-server-01",
            software_version="0.1.0",
        ),
        payload={
            "metrics": [
                {
                    "name": "loss",
                    "value": 0.42,
                    "unit": None,
                    "tags": {"split": "train"},
                }
            ]
        },
    )


def test_create_worker():
    async def scenario():
        worker = TelemetryWorker(
            handler=lambda message: asyncio.sleep(0), max_queue_size=2
        )

        assert worker.queue.maxsize == 2
        assert worker.queue.qsize() == 0

    asyncio.run(scenario())


def test_queue_rejects_when_full():
    async def scenario():
        started = asyncio.Event()
        release = asyncio.Event()

        async def slow_handler(message):
            started.set()
            await release.wait()

        worker = TelemetryWorker(handler=slow_handler, max_queue_size=1)

        worker.start()

        worker.submit(make_message(1))

        # Wait until the first message is being processed,
        await started.wait()

        # The worker is busy
        worker.submit(make_message(2))

        # The next message must be rejected immediately
        with pytest.raises(asyncio.QueueFull):
            worker.submit(make_message(3))

        release.set()

        await worker.queue.join()
        await worker.stop()

    asyncio.run(scenario())


def test_worker_processes_messages_on_stop():
    async def scenario():
        processed = []

        async def handler(message):
            processed.append(message.sequence)

        worker = TelemetryWorker(handler=handler, max_queue_size=10)

        worker.start()

        worker.submit(make_message(1))
        worker.submit(make_message(2))
        worker.submit(make_message(3))

        await worker.queue.join()
        await worker.stop()

        assert processed == [1, 2, 3]

    asyncio.run(scenario())


def test_worker_survives_handler_exception():
    async def scenario():
        processed = []

        async def handler(message):
            if message.sequence == 1:
                raise ValueError("Simulated processing failure")

            processed.append(message.sequence)

        worker = TelemetryWorker(handler=handler, max_queue_size=10)

        worker.start()

        worker.submit(make_message(1))
        worker.submit(make_message(2))

        await worker.queue.join()
        await worker.stop()

        assert processed == [2]

    asyncio.run(scenario())


def test_worker_stops_cleanly():
    async def scenario():
        worker = TelemetryWorker(handler=lambda message: asyncio.sleep(0))

        worker.start()

        assert worker.is_running

        await worker.stop()

        assert not worker.is_running

    asyncio.run(scenario())


def test_cannot_submit_before_start():
    worker = TelemetryWorker(handler=lambda message: asyncio.sleep(0))

    with pytest.raises(RuntimeError):
        worker.submit(make_message())
